<template>
	<div class="wechat-robot-config-container mobile-robot-config">
		<el-card v-if="canViewConfig" shadow="hover">
			<div class="config-header">
				<div>
					<h3>微信群机器人配置</h3>
					<p>所有设置按微信群隔离，每个分类独立保存。</p>
				</div>
				<div class="header-actions"><el-button v-if="overview" @click="openSettingsPreview">预览查询设置</el-button><el-select v-model="selectedGroupId" filterable placeholder="请选择微信群" style="width: 320px" @change="loadOverview"><el-option v-for="group in groupOptions" :key="group.id" :label="groupOptionLabel(group)" :value="group.id" /></el-select></div>
			</div>

			<el-alert v-if="errorMessage" :title="errorMessage" type="error" show-icon :closable="false" class="mb15" />
			<el-skeleton v-if="loading && !overview" :rows="6" animated />

			<template v-else-if="overview">
				<div class="mobile-record-card__fields robot-config-mobile-summary"><div><dt>绑定机器人</dt><dd>{{ overview.robotName || '-' }}</dd></div><div><dt>群状态</dt><dd>{{ overview.groupStatus === 1 ? '启用' : '停用' }}</dd></div><div><dt>机器人状态</dt><dd>{{ robotAvailable ? '在线' : '不可用' }}</dd></div></div>
				<el-descriptions :column="4" border class="mb15 overview-status">
					<el-descriptions-item label="绑定机器人">{{ overview.robotName || '-' }}</el-descriptions-item>
					<el-descriptions-item label="群状态">
						<el-tag :type="overview.groupStatus === 1 ? 'success' : 'info'">{{ overview.groupStatus === 1 ? '启用' : '停用' }}</el-tag>
					</el-descriptions-item>
					<el-descriptions-item label="机器人状态">
						<el-tag :type="robotAvailable ? 'success' : 'danger'">{{ robotAvailable ? '在线' : '不可用' }}</el-tag>
					</el-descriptions-item>
					<el-descriptions-item label="固定档">
						<el-tag :type="overview.fixedScheduleEnabled === 1 ? 'success' : 'info'">{{ overview.fixedScheduleEnabled === 1 ? '已开启' : '未开启' }}</el-tag>
					</el-descriptions-item>
				</el-descriptions>

				<el-tabs v-model="activeTab" :tab-position="tabPosition" class="config-tabs">
					<el-tab-pane v-for="tab in tabs" :key="tab.name" :label="tab.label" :name="tab.name">
						<template v-if="tab.name === 'basic'">
							<div class="panel-heading">
								<div><h4>基础信息</h4><p>本阶段仅展示数据库真实状态，不提供修改。</p></div>
							</div>
							<el-descriptions :column="2" border>
								<el-descriptions-item label="微信群名称">{{ overview.groupName || '-' }}</el-descriptions-item>
								<el-descriptions-item label="微信群 wxid">{{ overview.groupWxid || '-' }}</el-descriptions-item>
								<el-descriptions-item label="厅号">{{ overview.hallNo || '未设置' }}</el-descriptions-item>
								<el-descriptions-item label="群备注">{{ overview.remark || '-' }}</el-descriptions-item>
								<el-descriptions-item label="运行状态">{{ overview.runningStatus === 1 ? '运行中' : '已停止' }}</el-descriptions-item>
								<el-descriptions-item label="账号健康状态">{{ overview.healthStatus || 'UNKNOWN' }}</el-descriptions-item>
								<el-descriptions-item label="最近成员同步">{{ overview.lastSuccessfulMemberSyncAt || '-' }}</el-descriptions-item>
								<el-descriptions-item label="Callback">
									<span :class="{ 'error-text': overview.callbackError }">{{ overview.callbackError || overview.callbackConfiguredAt || '-' }}</span>
								</el-descriptions-item>
							</el-descriptions>
						</template>
						<template v-else-if="tab.name === 'queue'">
							<div class="panel-heading"><div><h4>麦序规则</h4><p>保存后只影响后续新命令，不自动重排当前麦序。</p></div><el-button v-if="canSaveQueueRules" type="primary" :loading="queueSaving" @click="saveQueueRuleForm">保存本页</el-button></div>
							<el-form :model="queueRules" label-width="130px" class="queue-form">
								<el-row :gutter="18"><el-col :xs="24" :md="12"><el-form-item label="扣排人数"><el-input-number v-model="queueRules.slotCount" :min="1" :max="8" /></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="手速优先人数"><el-input-number v-model="queueRules.speedPriorityCount" :min="0" :max="queueRules.slotCount" /></el-form-item></el-col></el-row>
								<el-row :gutter="18"><el-col :xs="24" :md="12"><el-form-item label="特殊置顶人数"><el-input-number v-model="queueRules.specialTopCount" :min="0" :max="queueRules.slotCount" /></el-form-item></el-col></el-row>
								<el-row :gutter="18"><el-col :xs="24" :md="12"><el-form-item label="手速排允许取排"><el-switch v-model="queueRules.speedTakeEnabled" :active-value="1" :inactive-value="0" /></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="任务排允许取排"><el-switch v-model="queueRules.taskTakeEnabled" :active-value="1" :inactive-value="0" /></el-form-item></el-col></el-row>
								<el-row :gutter="18"><el-col :xs="24" :md="12"><el-form-item label="P8模式"><el-select v-model="queueRules.p8Mode"><el-option label="普通麦位" value="NORMAL" /><el-option label="保留麦位" value="RESERVED" /><el-option label="仅任务排老板位" value="TASK_ONLY" /></el-select></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="P8名称"><el-input v-model="queueRules.p8Name" maxlength="32" /></el-form-item></el-col></el-row>
							</el-form>
							<el-alert title="特殊置顶人数与手速优先人数之和不能超过扣排人数" type="info" :closable="false" class="mb15" />
							<el-divider content-position="left">新人一次性特殊置顶资格</el-divider>
							<div class="qualification-toolbar"><el-select v-if="canGrantSpecialTop" v-model="grantMemberWxid" filterable placeholder="选择当前在群成员" style="width:260px"><el-option v-for="member in specialCandidates" :key="member.memberWxid" :label="member.memberName" :value="member.memberWxid" /></el-select><el-button v-if="canGrantSpecialTop" type="primary" @click="grantSpecialTop">发放资格</el-button><el-select v-model="specialStatus" style="width:150px" @change="loadSpecialTop"><el-option label="可用" value="AVAILABLE" /><el-option label="已使用" value="CONSUMED" /><el-option label="已取消" value="CANCELLED" /></el-select></div>
							<el-table :data="specialList" border stripe><el-table-column prop="memberName" label="成员" min-width="150" /><el-table-column prop="memberWxid" label="wxid" min-width="200" /><el-table-column prop="status" label="状态" width="100" /><el-table-column prop="grantedAt" label="发放时间" width="170" /><el-table-column label="操作" width="90"><template #default="{row}"><el-button v-if="row.status==='AVAILABLE' && canCancelSpecialTop" text type="danger" @click="cancelSpecialTop(row)">取消</el-button></template></el-table-column></el-table>
						</template>
						<template v-else-if="tab.name === 'timing'">
							<div class="panel-heading"><div><h4>定时排档</h4><p>时间配置真实控制自动消息与命令窗口。</p></div><el-button v-if="canSaveTiming" type="primary" :loading="timingSaving" @click="saveTimingForm">保存本页</el-button></div>
							<el-form :model="timing" label-width="150px"><el-row :gutter="18"><el-col v-for="field in timingFields" :key="field.key" :xs="24" :md="12"><el-form-item :label="field.label"><el-input-number v-model="timing[field.key]" :min="field.min" :max="field.max" /></el-form-item></el-col></el-row></el-form>
							<el-divider content-position="left">启用排档时段</el-divider><div class="hour-actions"><el-button @click="timing.activeHours=allHours.slice()">全选</el-button><el-button @click="timing.activeHours=[]">清空</el-button></div><el-checkbox-group v-model="timing.activeHours" class="hour-grid"><el-checkbox v-for="hour in allHours" :key="hour" :value="hour" border><strong>{{hour}}-{{hour+1}}</strong><small>{{hostStateText(hour)}}</small></el-checkbox></el-checkbox-group>
						</template>
						<template v-else-if="tab.name === 'schedule'">
							<div class="panel-heading"><div><h4>固定档与主持</h4><p>24小时循环配置；CREATED立即同步，RUNNING不改。</p></div><div><el-button v-if="canBatchPlan" @click="openBatchPlan">批量设置</el-button><el-button v-if="canExceptions" @click="openExceptions">当天例外</el-button><el-button v-if="canPlanAudit" @click="openPlanAudit">审计</el-button></div></div>
							<el-table :data="schedulePlan.rows" border stripe max-height="620"><el-table-column label="时段" width="82"><template #default="{row}">{{row.hour}}-{{row.hour+1}}</template></el-table-column><el-table-column label="固定成员" min-width="260"><template #default="{row}"><el-tag v-for="m in row.fixedMembers" :key="m.memberWxid" :type="m.isPresent?'success':'danger'" class="mr5">{{m.memberName}}{{m.isPresent?'':'（已离群）'}}</el-tag><span v-if="!row.fixedMembers.length">-</span></template></el-table-column><el-table-column label="主持" min-width="150"><template #default="{row}">{{row.host.type==='OPEN'?'开厅':row.host.name||'未设置'}}</template></el-table-column><el-table-column prop="roundState" label="当前档状态" width="110"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button v-if="canSavePlan" text type="primary" @click="editPlanRow(row)">编辑</el-button></template></el-table-column></el-table>
						</template>
						<template v-else-if="tab.name === 'report'">
							<div class="panel-heading"><div><h4>报备回厅</h4><p>配置仅影响新报备；关闭功能会静默关闭当前全部报备。</p></div><div><el-button v-if="canReportAudit" @click="openReportAudit">审计</el-button><el-button v-if="canSaveReport" type="primary" :loading="reportSaving" @click="saveReportForm">保存本页</el-button></div></div>
							<el-form :model="reportConfig" label-width="140px" :disabled="!canSaveReport">
								<el-row :gutter="18"><el-col :xs="24" :md="12"><el-form-item label="启用报备"><el-switch v-model="reportConfig.enabled" :active-value="1" :inactive-value="0" /></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="当前名额"><strong>{{reportConfig.activeCount}} / {{reportConfig.maxReportCount}}</strong></el-form-item></el-col></el-row>
								<el-row :gutter="18"><el-col :xs="24" :md="12"><el-form-item label="最大报备人数"><el-input-number v-model="reportConfig.maxReportCount" :min="1" :max="reportConfig.slotCount" /></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="报备有效分钟"><el-input-number v-model="reportConfig.reportMinutes" :min="1" :max="1440" /></el-form-item></el-col></el-row>
								<el-form-item label="报备开始文字"><el-input v-model="reportConfig.startText" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item>
								<el-form-item label="报备结束文字"><el-input v-model="reportConfig.endText" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item>
							</el-form>
							<el-divider content-position="left">当前 ACTIVE 报备</el-divider>
							<el-table v-if="canActiveReports" :data="activeReports" border stripe><el-table-column prop="memberName" label="成员" min-width="130"/><el-table-column prop="memberWxid" label="wxid" min-width="190"/><el-table-column prop="reportContent" label="报备内容" min-width="160"/><el-table-column prop="reportedAt" label="报备时间" width="170"/><el-table-column prop="dueAt" label="最迟回厅" width="170"/><el-table-column prop="remindStatus" label="提醒" width="90"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="canCloseReport" text type="danger" @click="closeActiveReport(row)">提前关闭</el-button></template></el-table-column></el-table>
							<el-empty v-else description="没有查看当前报备的权限" />
						</template>
						<template v-else-if="tab.name === 'checkin'">
							<div class="panel-heading"><div><h4>打卡统计</h4><p>只控制统计展示，不删除或停止采集考勤与麦序事件。</p></div><div><el-button v-if="canStatisticsAudit" @click="openStatisticsAudit">审计</el-button><el-button v-if="canSaveStatistics" type="primary" :loading="statisticsSaving" @click="saveStatisticsForm">保存本页</el-button></div></div>
							<el-row v-if="canReadStatistics" :gutter="18"><el-col :xs="24" :lg="14"><el-form :model="statisticsConfig" label-width="150px" :disabled="!canSaveStatistics"><el-form-item label="统计总开关"><el-switch v-model="statisticsConfig.enabled" :active-value="1" :inactive-value="0"/><span class="form-tip">关闭后仍发送 :59 下一档简版，整点静默开档</span></el-form-item><el-divider content-position="left">显示内容</el-divider><el-row :gutter="16"><el-col v-for="field in statisticsFields" :key="field.key" :xs="24" :md="12"><el-form-item :label="field.label"><el-switch v-model="statisticsConfig[field.key]" :active-value="1" :inactive-value="0"/></el-form-item></el-col></el-row></el-form></el-col><el-col :xs="24" :lg="10"><el-card shadow="never" class="statistics-preview"><template #header><strong>效果预览</strong></template><pre>{{statisticsPreview}}</pre></el-card></el-col></el-row><el-empty v-else description="没有查看打卡统计配置的权限"/>
						</template>
						<template v-else-if="tab.name === 'queueMode'">
							<div class="panel-heading"><div><h4>扣排模式</h4><p>当前仅开放普通文本扣排。</p></div></div>
							<el-descriptions :column="1" border><el-descriptions-item label="当前模式">{{overview.queueMode==='NORMAL'?'普通模式':overview.queueMode}}</el-descriptions-item><el-descriptions-item label="支持口令">p / P / 排 / 补</el-descriptions-item><el-descriptions-item label="状态"><el-tag type="success">已启用</el-tag></el-descriptions-item><el-descriptions-item label="说明">其他扣排模式暂未开放</el-descriptions-item></el-descriptions>
						</template>
						<template v-else-if="tab.name === 'permission'">
							<div class="panel-heading"><div><h4>权限与提醒</h4><p>管理三来源管理员、任务未过分钟和自动群提醒。</p></div><el-button v-if="canPermissionAudit" @click="openPermissionAudit">审计</el-button></div>
							<el-card v-if="canReadTiming" shadow="never" class="mb15"><template #header><strong>任务未过提醒分钟</strong></template><el-form-item label="提醒分钟"><el-select v-model="timing.taskReminderMinutes" multiple collapse-tags clearable placeholder="留空表示关闭"><el-option v-for="minute in reminderMinutes" :key="minute" :label="`${minute}分`" :value="minute" /></el-select></el-form-item><div class="template-actions"><el-button v-if="canSaveTaskReminders" type="primary" :loading="timingSaving" @click="saveTaskReminderForm">保存任务提醒</el-button></div></el-card>
							<el-tabs v-model="permissionSubTab"><el-tab-pane v-if="canReadAdmins" label="管理员" name="admins"/><el-tab-pane v-if="canReadReminders" label="自动提醒" name="reminders"/></el-tabs>
							<template v-if="permissionSubTab==='admins'&&canReadAdmins"><div class="admin-toolbar"><el-select v-if="canSavePermanentAdmin" v-model="permanentAdminWxid" filterable placeholder="选择当前在群成员"><el-option v-for="m in specialCandidates" :key="m.memberWxid" :label="m.memberName" :value="m.memberWxid"/></el-select><el-button v-if="canSavePermanentAdmin" type="primary" @click="savePermanentAdmin">新增永久管理员</el-button><span>最近同步：{{permissionSyncAt||'-'}}</span></div><el-table :data="permissionAdmins" border><el-table-column prop="memberName" label="成员"/><el-table-column prop="memberWxid" label="wxid" min-width="190"/><el-table-column label="来源"><template #default="{row}"><el-tag v-for="source in row.sources" :key="source" class="mr5">{{source}}</el-tag></template></el-table-column><el-table-column label="群状态" width="90"><template #default="{row}">{{row.isPresent===1?'在群':'已离群'}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button v-if="canDeletePermanentAdmin&&row.sources.includes('PERMANENT_ADMIN')" text type="danger" @click="deletePermanentAdmin(row)">删除</el-button></template></el-table-column></el-table></template>
							<template v-else-if="permissionSubTab==='reminders'&&canReadReminders"><el-table :data="reminderConfigs" border><el-table-column prop="label" label="提醒场景"/><el-table-column label="是否发送" width="130"><template #default="{row}"><el-switch v-model="row.enabled" :active-value="1" :inactive-value="0" :disabled="!canSaveReminders"/></template></el-table-column><el-table-column label="原生@所有人" width="150"><template #default="{row}"><el-switch v-model="row.atAllEnabled" :active-value="1" :inactive-value="0" :disabled="!canSaveReminders||row.enabled!==1"/></template></el-table-column></el-table><div class="template-actions"><el-button v-if="canSaveReminders" type="primary" @click="saveReminderConfig">保存自动提醒</el-button></div></template>
							<el-empty v-else description="没有查看权限与提醒的权限"/>
						</template>
						<template v-else-if="tab.name === 'template'">
							<div class="panel-heading"><div><h4>命令与回复</h4><p>管理当前群命令权限、群私有口令和回复模板。</p></div><div><el-button @click="router.push('/wechat/template')">完整模板管理</el-button><el-button v-if="canTemplateAudit" @click="openTemplateAudit">模板审计</el-button></div></div>
							<template v-if="canReadTemplates"><div class="template-toolbar"><el-input v-model="templateKeyword" clearable placeholder="搜索命令名称、key或口令"/><el-select v-model="templateKind"><el-option label="全部类型" value=""/><el-option label="主动命令" value="COMMAND"/><el-option label="自动场景" value="AUTO"/></el-select></div>
							<el-table v-if="canReadTemplates" :data="filteredTemplateCommands" row-key="commandKey" border stripe max-height="650"><el-table-column type="expand"><template #default="{row}"><div class="template-command-editor"><el-form label-width="115px" :disabled="!canSaveTemplates"><el-form-item v-if="row.executionMode" label="本人执行"><el-radio-group v-model="row.executionMode"><el-radio-button value="ALL">所有人</el-radio-button><el-radio-button value="ADMIN_ONLY">仅管理员</el-radio-button><el-radio-button value="DISABLED" :disabled="row.commandKey==='START_RUNNING'">完全禁用</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="row.delegationMode" label="是否代发"><el-radio-group v-model="row.delegationMode"><el-radio-button value="ALL">所有人</el-radio-button><el-radio-button value="ADMIN_ONLY">仅管理员</el-radio-button><el-radio-button value="DISABLED">禁止代发</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="row.delegationMode" label="群私有口令"><el-input v-model="row.aliasInput" type="textarea" :rows="2" placeholder="每行一个；留空继承公共口令"/></el-form-item><el-form-item label="公共口令"><el-tag v-for="alias in row.publicAliases" :key="alias" class="mr5">{{alias}}</el-tag><span v-if="!row.publicAliases.length">无固定口令</span></el-form-item></el-form><el-card v-for="scenario in row.scenarios" :key="scenario.eventKey" shadow="never" class="scenario-card"><template #header><div class="scenario-header"><strong>{{scenario.label}}</strong><el-select v-model="scenario.state" :disabled="!canSaveTemplates" style="width:170px"><el-option label="使用公共默认" value="PUBLIC"/><el-option label="群私有启用" value="GROUP_ENABLED"/><el-option label="当前群禁用" value="GROUP_DISABLED"/></el-select></div></template><el-alert v-if="scenario.state==='PUBLIC'" title="当前使用公共默认" type="info" :closable="false"/><el-input v-else v-model="scenario.groupContent" type="textarea" :rows="5" :disabled="!canSaveTemplates||scenario.state==='GROUP_DISABLED'"/><div class="variable-list"><el-tag v-for="variable in scenario.allowedVariables" :key="variable" size="small">{{variableToken(variable)}}</el-tag></div></el-card><div class="template-actions"><el-button v-if="canResetTemplates" type="danger" plain @click="resetTemplateCommand(row)">恢复公共默认</el-button><el-button v-if="canSaveTemplates" type="primary" @click="saveTemplateCommand(row)">保存本命令</el-button></div></div></template></el-table-column><el-table-column prop="commandName" label="命令名称" min-width="150"/><el-table-column prop="commandUsage" label="直观口令" min-width="220"><template #default="{row}"><span class="multiline-text">{{row.commandUsage||'定时触发'}}</span></template></el-table-column><el-table-column label="本人执行" width="105"><template #default="{row}">{{delegationModeLabel(row.executionMode)}}</template></el-table-column><el-table-column label="代发" width="105"><template #default="{row}">{{delegationModeLabel(row.delegationMode)}}</template></el-table-column></el-table></template>
							<el-empty v-else description="没有查看模板与口令的权限"/>
						</template>
						<template v-else>
							<div class="panel-heading"><div><h4>{{ tab.label }}</h4><p>{{ tab.description }}</p></div></div>
							<el-empty description="该分类将在业务规则确认并完成真实接入后开放" />
						</template>
					</el-tab-pane>
				</el-tabs>
				<div class="robot-mobile-table-cards">
					<MobileRecordList v-if="activeTab==='queue'" :data="specialList" row-key="id"><template #default="{row}"><div class="mobile-record-card__header"><h3 class="mobile-record-card__title">{{row.memberName}}</h3><el-tag>{{row.status}}</el-tag></div><dl class="mobile-record-card__fields"><div><dt>wxid</dt><dd>{{row.memberWxid}}</dd></div><div><dt>发放时间</dt><dd>{{row.grantedAt||'-'}}</dd></div></dl><div class="mobile-record-card__actions"><el-button v-if="row.status==='AVAILABLE'&&canCancelSpecialTop" type="danger" @click="cancelSpecialTop(row)">取消</el-button></div></template></MobileRecordList>
