const canSavePlan=auth('api/v1/system/wechatRobotGroup/schedulePlanSave');const canBatchPlan=auth('api/v1/system/wechatRobotGroup/schedulePlanBatchSave');const canExceptions=auth('api/v1/system/wechatRobotGroup/scheduleExceptions');const canPlanAudit=auth('api/v1/system/wechatRobotGroup/schedulePlanAudit');
