	if (!selectedGroupId.value || !canViewConfig) return;
	loading.value = true;
	errorMessage.value = '';
	try {
		const res: any = await getWechatRobotGroupConfigOverview(selectedGroupId.value);
		overview.value = res.data;
	} catch (error: any) {
		overview.value = undefined;
		errorMessage.value = error?.message || '机器人配置加载失败';
	} finally {
		loading.value = false;
	}
};

const openSettingsPreview = async () => {
	await loadOverview();
	if (overview.value?.settingsPreview) settingsPreviewDialog.value = true;
};

const loadGroups = async () => {
	if (!canViewConfig) return;
	loading.value = true;
	try {
		const res: any = await getWechatRobotGroupList({ pageNum: 1, pageSize: 999 });
		groupOptions.value = res.data.list || [];
		const requestedGroupId = Number(route.query.groupId || 0);
		const requestedExists = groupOptions.value.some((group: any) => group.id === requestedGroupId);
		selectedGroupId.value = requestedExists ? requestedGroupId : groupOptions.value[0]?.id;
		if (selectedGroupId.value) {
			await loadOverview();
		}
	} catch (error: any) {
		errorMessage.value = error?.message || '微信群列表加载失败';
	} finally {
		loading.value = false;
	}
};

const loadQueueRules=async()=>{if(!selectedGroupId.value||!canReadQueueRules)return;const res:any=await getWechatRobotGroupQueueRules(selectedGroupId.value);Object.assign(queueRules,res.data);};
const loadSpecialTop=async()=>{if(!selectedGroupId.value||!canListSpecialTop)return;const res:any=await getWechatRobotGroupSpecialTopList(selectedGroupId.value,specialStatus.value);specialList.value=res.data.list||[];specialCandidates.value=res.data.candidates||[];};
const loadQueueTab=async()=>{await Promise.all([loadQueueRules(),loadSpecialTop()]);};
const saveQueueRuleForm=async()=>{if(!selectedGroupId.value)return;if(queueRules.specialTopCount+queueRules.speedPriorityCount>queueRules.slotCount){ElMessage.error('特殊置顶人数与手速优先人数之和不能超过扣排人数');return;}queueSaving.value=true;try{const res:any=await saveWechatRobotGroupQueueRules({groupId:selectedGroupId.value,...queueRules});Object.assign(queueRules,res.data);ElMessage.success('麦序规则已保存');}finally{queueSaving.value=false;}};
const grantSpecialTop=async()=>{if(!selectedGroupId.value||!grantMemberWxid.value)return;const member=specialCandidates.value.find((item:any)=>item.memberWxid===grantMemberWxid.value);await grantWechatRobotGroupSpecialTop({groupId:selectedGroupId.value,memberWxid:grantMemberWxid.value,memberName:member?.memberName||''});grantMemberWxid.value='';ElMessage.success('特殊置顶资格已发放');await loadSpecialTop();};
const cancelSpecialTop=async(row:any)=>{if(!selectedGroupId.value)return;await ElMessageBox.confirm(`确认取消 ${row.memberName||row.memberWxid} 的特殊置顶资格？`,'提示',{type:'warning'});await cancelWechatRobotGroupSpecialTop({groupId:selectedGroupId.value,id:row.id});ElMessage.success('资格已取消');await loadSpecialTop();};
const loadTiming=async()=>{if(!selectedGroupId.value||!canReadTiming)return;const res:any=await getWechatRobotGroupScheduleTiming(selectedGroupId.value);Object.assign(timing,res.data,{taskReminderMinutes:[...(res.data.taskReminderMinutes||[])].sort((a:number,b:number)=>a-b)});savedCreateMinute=timing.scheduleCreateMinute;};const hostStateText=(hour:number)=>{const state=timing.hostStates?.find((item:any)=>item.hour===hour);return state?.type==='REAL'?state.name:state?.type==='OPEN'?'开厅':'未设置'};const saveTimingForm=async()=>{if(!selectedGroupId.value)return;if(timing.scheduleCreateMinute!==savedCreateMinute)await ElMessageBox.confirm('修改麦序开始分钟可能跳过下一小时自动发排，保存后不会补发已错过消息。确认继续？','提示',{type:'warning'});timingSaving.value=true;try{const res:any=await saveWechatRobotGroupScheduleTiming({groupId:selectedGroupId.value,scheduleCreateMinute:timing.scheduleCreateMinute,scheduleLockMinute:timing.scheduleLockMinute,supplementCloseMinutes:timing.supplementCloseMinutes,takeCloseMinutes:timing.takeCloseMinutes,p8PurchaseCloseMinutes:timing.p8PurchaseCloseMinutes,activeHours:timing.activeHours});Object.assign(timing,res.data);savedCreateMinute=timing.scheduleCreateMinute;ElMessage.success('定时排档已保存');}finally{timingSaving.value=false;}};
const saveTaskReminderForm=async()=>{if(!selectedGroupId.value)return;timingSaving.value=true;try{const taskReminderMinutes=[...new Set<number>(timing.taskReminderMinutes||[])].sort((a,b)=>a-b);const res:any=await saveWechatRobotGroupTaskReminderMinutes({groupId:selectedGroupId.value,taskReminderMinutes});Object.assign(timing,res.data);ElMessage.success('任务未过提醒已保存');}finally{timingSaving.value=false;}};
const loadSchedulePlan=async()=>{if(!selectedGroupId.value)return;const res:any=await getWechatRobotGroupSchedulePlan(selectedGroupId.value);Object.assign(schedulePlan,res.data);};const memberByWxid=(wxid:string)=>schedulePlan.candidates.find((m:any)=>m.memberWxid===wxid);const hostInput=(wxid:string)=>wxid==='virtual:open'?{wxid,name:'开厅',type:'OPEN',isPresent:1}:wxid?{wxid,name:memberByWxid(wxid)?.memberName||wxid,type:'REAL',isPresent:1}:{wxid:'',name:'',type:'UNSET',isPresent:0};const fixedInputs=(ids:string[])=>ids.map((wxid,index)=>({slotNo:index+1,memberWxid:wxid,memberName:memberByWxid(wxid)?.memberName||wxid,isPresent:1}));const editPlanRow=(row:any)=>{Object.assign(planForm,row);planFixedWxids.value=row.fixedMembers.map((m:any)=>m.memberWxid);planHostWxid.value=row.host.type==='OPEN'?'virtual:open':row.host.wxid||'';planDialog.value=true;};const savePlanRow=async()=>{const res:any=await saveWechatRobotGroupSchedulePlan({groupId:selectedGroupId.value,row:{hour:planForm.hour,fixedMembers:fixedInputs(planFixedWxids.value),host:hostInput(planHostWxid.value)}});Object.assign(schedulePlan,res.data);planDialog.value=false;ElMessage.success('小时排班已保存');};const openBatchPlan=()=>{batchHours.value=[];batchFixedWxids.value=[];batchHostWxid.value='';batchDialog.value=true;};const saveBatchPlan=async()=>{const res:any=await batchSaveWechatRobotGroupSchedulePlan({groupId:selectedGroupId.value,hours:batchHours.value,fixedMembers:fixedInputs(batchFixedWxids.value),host:hostInput(batchHostWxid.value)});Object.assign(schedulePlan,res.data);batchDialog.value=false;};const clearBatchPlan=async()=>{await ElMessageBox.confirm('确认批量清空所选时段？','提示',{type:'warning'});const res:any=await batchClearWechatRobotGroupSchedulePlan({groupId:selectedGroupId.value,hours:batchHours.value,mode:clearMode.value});Object.assign(schedulePlan,res.data);batchDialog.value=false;};const loadExceptions=async()=>{if(!selectedGroupId.value)return;const res:any=await getWechatRobotGroupScheduleExceptions(selectedGroupId.value,exceptionDate.value);exceptions.value=res.data.list||[];};const openExceptions=()=>{exceptionDrawer.value=true;loadExceptions();};const saveFixedVoid=async()=>{const m=memberByWxid(exceptionMemberWxid.value);await saveWechatRobotGroupFixedException({groupId:selectedGroupId.value,businessDate:exceptionDate.value,hour:exceptionHour.value,memberWxid:exceptionMemberWxid.value,memberName:m?.memberName||''});await loadExceptions();};const saveHostOverride=async()=>{await saveWechatRobotGroupHostException({groupId:selectedGroupId.value,businessDate:exceptionDate.value,hour:exceptionHour.value,host:hostInput(exceptionHostWxid.value)});await loadExceptions();};const restoreException=async(row:any)=>{const fn=row.type==='FIXED_VOID'?restoreWechatRobotGroupFixedException:restoreWechatRobotGroupHostException;await fn({groupId:selectedGroupId.value,id:row.id});await loadExceptions();};const openPlanAudit=async()=>{const res:any=await getWechatRobotGroupSchedulePlanAudit(selectedGroupId.value!);planAudits.value=res.data.list||[];auditDrawer.value=true;};
const loadReport=async()=>{if(!selectedGroupId.value||!canReadReport)return;const [configRes,activeRes]:any[]=await Promise.all([getWechatRobotGroupReportConfig(selectedGroupId.value),canActiveReports?getWechatRobotGroupActiveReports(selectedGroupId.value):Promise.resolve({data:{list:[]}})]);Object.assign(reportConfig,configRes.data);activeReports.value=activeRes.data.list||[];};const saveReportForm=async()=>{if(!selectedGroupId.value)return;if(reportConfig.enabled===0&&reportConfig.activeCount>0)await ElMessageBox.confirm(`关闭后将静默关闭 ${reportConfig.activeCount} 条当前报备并释放名额，不发送群消息。确认继续？`,'关闭报备',{type:'warning'});reportSaving.value=true;try{const res:any=await saveWechatRobotGroupReportConfig({groupId:selectedGroupId.value,enabled:reportConfig.enabled,maxReportCount:reportConfig.maxReportCount,reportMinutes:reportConfig.reportMinutes,startText:reportConfig.startText,endText:reportConfig.endText});Object.assign(reportConfig,res.data);await loadReport();ElMessage.success('报备配置已保存');}finally{reportSaving.value=false;}};const closeActiveReport=async(row:any)=>{const result:any=await ElMessageBox.prompt(`提前关闭 ${row.memberName||row.memberWxid} 的报备，不会发送群消息。`,'提前关闭',{inputPlaceholder:'请输入关闭原因',inputValidator:(value:string)=>!!value.trim()||'关闭原因不能为空'});await closeWechatRobotGroupReport({groupId:selectedGroupId.value,reportId:row.id,reason:result.value});ElMessage.success('报备已提前关闭');await loadReport();};const openReportAudit=async()=>{const res:any=await getWechatRobotGroupReportConfigAudit(selectedGroupId.value!);reportAudits.value=res.data.list||[];reportAuditDrawer.value=true;};
const loadStatistics=async()=>{if(!selectedGroupId.value||!canReadStatistics)return;const res:any=await getWechatRobotGroupStatisticsConfig(selectedGroupId.value);Object.assign(statisticsConfig,res.data);};const saveStatisticsForm=async()=>{if(!selectedGroupId.value)return;statisticsSaving.value=true;try{const res:any=await saveWechatRobotGroupStatisticsConfig({groupId:selectedGroupId.value,...statisticsConfig});Object.assign(statisticsConfig,res.data);ElMessage.success('打卡统计配置已保存');}finally{statisticsSaving.value=false;}};const openStatisticsAudit=async()=>{const res:any=await getWechatRobotGroupStatisticsConfigAudit(selectedGroupId.value!);statisticsAudits.value=res.data.list||[];statisticsAuditDrawer.value=true;};
const loadTemplateCommands=async()=>{if(!selectedGroupId.value||!canReadTemplates)return;const res:any=await getWechatRobotGroupTemplateCommands(selectedGroupId.value);templateCommands.value=(res.data.list||[]).map((row:any)=>({...row,aliasInput:(row.groupAliases||[]).join('\n'),scenarios:(row.scenarios||[]).map((scenario:any)=>({...scenario,groupContent:scenario.groupContent||scenario.publicContent}))}));};const delegationModeLabel=(mode:string)=>mode==='ALL'?'所有人':mode==='ADMIN_ONLY'?'仅管理员':mode==='DISABLED'?'完全禁用':'不适用';const saveTemplateCommand=async(row:any)=>{await saveWechatRobotGroupTemplateCommand({groupId:selectedGroupId.value,commandKey:row.commandKey,aliases:row.aliasInput.split(/\r?\n/).map((value:string)=>value.trim()).filter(Boolean),executionMode:row.executionMode,delegationMode:row.delegationMode,scenarios:row.scenarios.map((scenario:any)=>({eventKey:scenario.eventKey,state:scenario.state,content:scenario.groupContent}))});ElMessage.success('模板与口令配置已保存');await loadTemplateCommands();};const resetTemplateCommand=async(row:any)=>{await ElMessageBox.confirm(`确认将“${row.commandName||row.commandKey}”恢复公共默认？群私有模板、口令和权限覆盖都会删除。`,'恢复公共默认',{type:'warning'});await resetWechatRobotGroupTemplateCommand({groupId:selectedGroupId.value,commandKey:row.commandKey});ElMessage.success('已恢复公共默认');await loadTemplateCommands();};const openTemplateAudit=async()=>{const res:any=await getWechatRobotGroupTemplateCommandAudit(selectedGroupId.value!);templateAudits.value=res.data.list||[];templateAuditDrawer.value=true;};
const loadPermissionAdmins=async()=>{if(!selectedGroupId.value||!canReadAdmins)return;const res:any=await getWechatRobotGroupPermissionAdmins(selectedGroupId.value);permissionAdmins.value=res.data.list||[];permissionSyncAt.value=res.data.lastSuccessfulSyncAt||'';};const savePermanentAdmin=async()=>{if(!selectedGroupId.value||!permanentAdminWxid.value)return;await saveWechatRobotGroupPermanentAdmin({groupId:selectedGroupId.value,memberWxid:permanentAdminWxid.value});permanentAdminWxid.value='';ElMessage.success('永久管理员已保存');await loadPermissionAdmins();};const deletePermanentAdmin=async(row:any)=>{await ElMessageBox.confirm(`确认删除 ${row.memberName||row.memberWxid} 的永久管理员？`,'提示',{type:'warning'});await deleteWechatRobotGroupPermanentAdmin({groupId:selectedGroupId.value,memberWxid:row.memberWxid});await loadPermissionAdmins();};
const loadReminderConfig=async()=>{if(!selectedGroupId.value||!canReadReminders)return;const res:any=await getWechatRobotGroupReminderConfig(selectedGroupId.value);reminderConfigs.value=(res.data.list||[]).map((row:any)=>({...row,label:reminderLabels[row.eventKey]||row.eventKey}));};const saveReminderConfig=async()=>{await saveWechatRobotGroupReminderConfig({groupId:selectedGroupId.value,list:reminderConfigs.value.map(({eventKey,enabled,atAllEnabled}:any)=>({eventKey,enabled,atAllEnabled}))});ElMessage.success('自动提醒配置已保存');};
const openPermissionAudit=async()=>{const res:any=await getWechatRobotGroupPermissionReminderAudit(selectedGroupId.value!);permissionAudits.value=res.data.list||[];permissionAuditDrawer.value=true;};
const loadPermissionSubTab=()=>{if(permissionSubTab.value==='admins'){loadSpecialTop();loadPermissionAdmins();}if(permissionSubTab.value==='reminders')loadReminderConfig();};
const loadPermissionTab=()=>{loadTiming();loadPermissionSubTab();};
watch(permissionSubTab,loadPermissionSubTab);watch(activeTab,(value)=>{if(value==='queue')loadQueueTab();if(value==='timing')loadTiming();if(value==='schedule')loadSchedulePlan();if(value==='report')loadReport();if(value==='checkin')loadStatistics();if(value==='permission')loadPermissionTab();if(value==='template')loadTemplateCommands();});watch(selectedGroupId,()=>{if(activeTab.value==='queue')loadQueueTab();if(activeTab.value==='timing')loadTiming();if(activeTab.value==='schedule')loadSchedulePlan();if(activeTab.value==='report')loadReport();if(activeTab.value==='checkin')loadStatistics();if(activeTab.value==='permission')loadPermissionTab();if(activeTab.value==='template')loadTemplateCommands();});

onMounted(() => {
	syncTabPosition();
	mobileMedia.addEventListener('change', syncTabPosition);
	loadGroups();
});
onBeforeUnmount(() => mobileMedia.removeEventListener('change', syncTabPosition));
</script>

